// dot-repel. Generated by scripts/build-esm.mjs from the DEFAULTS of the engine.

export interface DotRepelSettings {
  /** Colour of the dots. Default: '#15100c'. */
  color?: string;
  /** 0 to 1. Opacity of a dot at rest. Default: 0.12. */
  rest?: number;
  /** 0 to 1. Opacity of a dot pushed the farthest. Default: 0.34. */
  peak?: number;
  /** px, keep px. Distance between two dots. Default: 16. */
  spacing?: number;
  /** px, keep px. Radius of a dot at rest. Default: 1.2. */
  dot?: number;
  /** any CSS unit. Radius the pointer parts. Default: 'clamp(120px, 12vw, 180px)'. */
  reach?: string;
  /** times dot. Radius of a dot pushed the farthest. Default: 1.35. */
  grow?: number;
  /** times reach. How far the dots are pushed. Default: 0.28. */
  push?: number;
  /** s. Time a dot takes to spring back. Default: 0.9. */
  life?: number;
}

export interface Instance {
  destroy(): void;
  [key: string]: unknown;
}

export interface Library {
  mount(element: Element, settings?: DotRepelSettings): Instance | null;
  destroy(element: Element): void;
  auto(root?: ParentNode): void;
  defaults: Required<DotRepelSettings> | null;
  [key: string]: unknown;
}

/** Runs the engine once and returns window.DotRepel, or null on a server. */
export function load(): Library | null;
/** Mounts the effect on one element. Does nothing, and returns null, on a server. */
export function mount(element: Element | null, settings?: DotRepelSettings): Instance | null;
export function destroy(element: Element | null): void;
/** Mounts every marked element inside root, the document by default. */
export function auto(root?: ParentNode): void;
export function freeze(element: Element | null): void;
export function unfreeze(element: Element | null): void;
